#!/usr/bin/env bash
# Pre-launch v7 for the from-scratch pass (after astra gate-2 v5 HOLD). Stage local: comparator self-tests, fingerprint backfill, finalize (main-guarded), label-check delta,
# format-block rebuild, assemble (the assembler writes expected_train_rows into the config before hashing), recipe table. Stage cluster: upload, trainer dry-run, label inspection,
# preflight, brief, SEVENTH astra review. Stops before the launch (a separate command, owner's go). Fail-closed. Usage: bash cluster/r4_full_prelaunch_v7.sh local|cluster|all
set -u -o pipefail; cd ~/Projects/train-apertus-with-glossapi/subprojects/12_greek_sft_experiments; S=/iopsstor/scratch/cscs/fffoivos; R=$S/sft_round1; OUT=results/R4_full; mkdir -p $OUT
PY=$HOME/Projects/apertus-local-chat/.venv/bin/python; sshc(){ ssh -4 -o BatchMode=yes -o ConnectTimeout=30 -o ServerAliveInterval=30 clariden "$@" 2>/dev/null; }; say(){ echo "[$(date '+%m-%d %H:%M')] prelaunch7: $*"; }
STAGE=${1:-all}
if [ "$STAGE" = local ] || [ "$STAGE" = all ]; then
  say "self-tests (40 cases incl. the v6 counterexamples)"; $PY data/math/cut2/labelcheck_lib.py --selftest || { say "FAILED: comparator self-tests"; exit 1; }
  say "fingerprint backfill"; $PY data/math/cut2/backfill_solve_fingerprints.py | tail -1 || { say "FAILED: backfill"; exit 1; }
  cp data/math/cut2/final/label_disagreements.json $OUT/label_disagreements_prev.json
  say "finalize"; $PY data/math/cut2/finalize_label_check.py > $OUT/label_check.txt 2>&1 || { say "FAILED: finalize: $(tail -2 $OUT/label_check.txt | tr '\n' ' ' | cut -c1-300)"; exit 1; }; sed -n '2,3p' $OUT/label_check.txt | cut -c1-300
  $PY data/math/cut2/label_check_delta.py $OUT/label_disagreements_prev.json data/math/cut2/final/label_disagreements.json $OUT/label_check_delta.json | head -6
  say "format block rebuild"; (cd data/format_block && $PY build_mc_fewshot.py 2>&1 | tail -1 | cut -c1-300) || { say "FAILED: format block"; exit 1; }
  say "assembling R4_full"; $PY data/assemble_full_r4.py --arm R4_full > $OUT/assemble.log 2>&1 || { say "FAILED: assembly: $(tail -3 $OUT/assemble.log | tr '\n' ' ' | cut -c1-400)"; exit 1; }; tail -2 $OUT/assemble.log | cut -c1-400
  ROWS=$(wc -l < data/arms/R4_full/train.jsonl | tr -d ' '); grep -q "^expected_train_rows: $ROWS$" cluster/configs/R4_full.yaml || { say "FAILED: config rows not written by the assembler"; exit 1; }; say "config rows $ROWS (written by the assembler)"
  python3 data/recipe_table_r4_full.py | tail -1 | cut -c1-200
  say "LOCAL_DONE"
fi
if [ "$STAGE" = cluster ] || [ "$STAGE" = all ]; then
  say "upload + trainer dry-run"; sshc "mkdir -p $R/data/arms/R4_full" || { say "FAILED: ssh (certificate?)"; exit 1; }; scp -4 -q data/arms/R4_full/train.jsonl data/arms/R4_full/dev.jsonl clariden:$R/data/arms/R4_full/ && scp -4 -q cluster/configs/R4_full.yaml clariden:$R/cluster/configs/R4_full.yaml && scp -4 -q cluster/sft_train.py cluster/rendered_lengths.py cluster/inspect_trl_labels.py cluster/inspect_labels.py clariden:$R/cluster/ || { say "FAILED: upload"; exit 1; }
  [ "$(sshc "cd $R && md5sum data/arms/R4_full/train.jsonl | cut -c1-12")" = "$(md5 -q data/arms/R4_full/train.jsonl | cut -c1-12)" ] || { say "FAILED: md5 mismatch"; exit 1; }; say "md5 verified"
  sshc "cd $R && uenv run --view=default pytorch/v2.9.1:v2 -- bash -lc 'export SCRATCH=$S HF_HOME=$R/hf_home HF_HUB_CACHE=$R/hf_home/hub HF_HUB_OFFLINE=0 TRANSFORMERS_OFFLINE=0 HF_DATASETS_OFFLINE=1 HF_TOKEN=\$(cat $R/hf_home/token); source $S/venvs/sft5/bin/activate; python cluster/sft_train.py --config cluster/configs/R4_full.yaml --dry-run'" > $OUT/dryrun.log 2>&1 &
  D1=$!; sshc "cd $R && uenv run --view=default pytorch/v2.9.1:v2 -- bash -lc 'export SCRATCH=$S HF_HOME=$R/hf_home HF_HUB_CACHE=$R/hf_home/hub HF_HUB_OFFLINE=0 TRANSFORMERS_OFFLINE=0 HF_DATASETS_OFFLINE=1 HF_TOKEN=\$(cat $R/hf_home/token); source $S/venvs/sft5/bin/activate; python cluster/rendered_lengths.py --config cluster/configs/R4_full.yaml --train data/arms/R4_full/train.jsonl --dev data/arms/R4_full/dev.jsonl'" 2>/dev/null | grep -oE 'RENDERED_LENGTHS \{.*\}' | cut -c18- > $OUT/rendered_lengths.json &
  D2=$!; sshc "cd $R && uenv run --view=default pytorch/v2.9.1:v2 -- bash -lc 'export SCRATCH=$S HF_HOME=$R/hf_home HF_HUB_CACHE=$R/hf_home/hub HF_HUB_OFFLINE=0 TRANSFORMERS_OFFLINE=0 HF_DATASETS_OFFLINE=1 HF_TOKEN=\$(cat $R/hf_home/token); source $S/venvs/sft5/bin/activate; python cluster/inspect_trl_labels.py --config cluster/configs/R4_full.yaml --train data/arms/R4_full/train.jsonl 2>&1' | grep -v rope_parameters" > $OUT/trl_labels_inspection.txt &
  D3=$!; say "dry-run, rendered lengths and TRL-path labels running in parallel on the login node"; wait $D1 $D2 $D3
  grep -q '"max"' $OUT/rendered_lengths.json || { say "FAILED: rendered lengths: $(tail -c 300 $OUT/rendered_lengths.json)"; exit 1; }; say "rendered lengths: $(python3 -c "import json; d=json.load(open('$OUT/rendered_lengths.json')); print('train max', d['train']['max'], 'over', d['train']['over_max_length'], 'p99', d['train']['p99'], '| dev max', d['dev']['max'], 'over', d['dev']['over_max_length'])")"
  grep -q 'TRL_LABELS_CHECK OK' $OUT/trl_labels_inspection.txt || { say "FAILED: TRL labels: $(grep -E 'TRL_LABELS_CHECK|Error|Traceback' $OUT/trl_labels_inspection.txt | tail -2 | cut -c1-300)"; exit 1; }; say "TRL labels: $(grep TRL_LABELS_CHECK $OUT/trl_labels_inspection.txt | cut -c1-200)"
  grep -q DRY_RUN_OK $OUT/dryrun.log || { say "FAILED: dry-run: $(tail -3 $OUT/dryrun.log | tr '\n' ' ' | cut -c1-300)"; exit 1; }; say "dry-run OK: $(grep -oE 'PLAN \{.*\}' $OUT/dryrun.log | cut -c1-300)"
  sshc "cd $R && uenv run --view=default pytorch/v2.9.1:v2 -- bash -lc 'export SCRATCH=$S HF_HOME=$R/hf_home HF_HUB_CACHE=$R/hf_home/hub HF_HUB_OFFLINE=0 TRANSFORMERS_OFFLINE=0 HF_DATASETS_OFFLINE=1 HF_TOKEN=\$(cat $R/hf_home/token); source $S/venvs/sft5/bin/activate; python cluster/inspect_labels.py --config cluster/configs/R4_full.yaml --train data/arms/R4_full/train.jsonl'" 2>/dev/null | grep -v "rope_parameters" > $OUT/labels_inspection.txt; say "label inspection: $(grep -c "^===" $OUT/labels_inspection.txt) rows inspected"
  bash cluster/preflight.sh 7 "R4_full_train" | tail -1 > $OUT/preflight.txt; cat $OUT/preflight.txt; grep -q '^OK' $OUT/preflight.txt || { say "FAILED: preflight refused"; exit 1; }
  python3 data/make_gate2_brief.py || { say "FAILED: brief"; exit 1; }
  say "astra gate-2 review (seventh)"; python3 data/review_astra.py gate2_full_v7 docs/reviews/briefs/astra_gate2_full_v7.md docs/reviews/ASTRA_gate2_full_v7_20260915.md --model gpt-6-astra --effort xhigh > logs/astra_gate2_full_v7.log 2>&1 || { say "FAILED: review: $(tail -2 logs/astra_gate2_full_v7.log | tr '\n' ' ' | cut -c1-200)"; exit 1; }
  say "verdict: $(grep -m1 -A2 -i '## 1. Verdict' docs/reviews/ASTRA_gate2_full_v7_20260915.md | tail -1 | cut -c1-300)"; say "PRELAUNCH_DONE"
fi
if [ "$STAGE" = resume ]; then   # after a failed check: scripts re-uploaded, rendered lengths + TRL labels re-run in parallel, then inspection, preflight, brief, review (dry-run of this manifest must already be OK)
  grep -q DRY_RUN_OK $OUT/dryrun.log && [ $OUT/dryrun.log -nt data/arms/R4_full/train.jsonl ] || { say "FAILED: resume needs a DRY_RUN_OK newer than the manifest"; exit 1; }
  scp -4 -q cluster/rendered_lengths.py cluster/inspect_trl_labels.py cluster/inspect_labels.py clariden:$R/cluster/ || { say "FAILED: script upload"; exit 1; }; say "scripts uploaded; dry-run already OK"
  if grep -q '"max"' $OUT/rendered_lengths.json 2>/dev/null && [ $OUT/rendered_lengths.json -nt data/arms/R4_full/train.jsonl ]; then say "rendered lengths already computed for this manifest"; (true) & else sshc "cd $R && uenv run --view=default pytorch/v2.9.1:v2 -- bash -lc 'export SCRATCH=$S HF_HOME=$R/hf_home HF_HUB_CACHE=$R/hf_home/hub HF_HUB_OFFLINE=0 TRANSFORMERS_OFFLINE=0 HF_DATASETS_OFFLINE=1 HF_TOKEN=\$(cat $R/hf_home/token); source $S/venvs/sft5/bin/activate; python cluster/rendered_lengths.py --config cluster/configs/R4_full.yaml --train data/arms/R4_full/train.jsonl --dev data/arms/R4_full/dev.jsonl'" 2>/dev/null | grep -oE 'RENDERED_LENGTHS \{.*\}' | cut -c18- > $OUT/rendered_lengths.json & fi
  D2=$!; sshc "cd $R && uenv run --view=default pytorch/v2.9.1:v2 -- bash -lc 'export SCRATCH=$S HF_HOME=$R/hf_home HF_HUB_CACHE=$R/hf_home/hub HF_HUB_OFFLINE=0 TRANSFORMERS_OFFLINE=0 HF_DATASETS_OFFLINE=1 HF_TOKEN=\$(cat $R/hf_home/token); source $S/venvs/sft5/bin/activate; python cluster/inspect_trl_labels.py --config cluster/configs/R4_full.yaml --train data/arms/R4_full/train.jsonl 2>&1' | grep -v rope_parameters" > $OUT/trl_labels_inspection.txt &
  D3=$!; say "dry-run, rendered lengths and TRL-path labels running in parallel on the login node"; wait $D2 $D3
  grep -q '"max"' $OUT/rendered_lengths.json || { say "FAILED: rendered lengths: $(tail -c 300 $OUT/rendered_lengths.json)"; exit 1; }; say "rendered lengths: $(python3 -c "import json; d=json.load(open('$OUT/rendered_lengths.json')); print('train max', d['train']['max'], 'over', d['train']['over_max_length'], 'p99', d['train']['p99'], '| dev max', d['dev']['max'], 'over', d['dev']['over_max_length'])")"
  grep -q 'TRL_LABELS_CHECK OK' $OUT/trl_labels_inspection.txt || { say "FAILED: TRL labels: $(grep -E 'TRL_LABELS_CHECK|Error|Traceback' $OUT/trl_labels_inspection.txt | tail -2 | cut -c1-300)"; exit 1; }; say "TRL labels: $(grep TRL_LABELS_CHECK $OUT/trl_labels_inspection.txt | cut -c1-200)"
  grep -q DRY_RUN_OK $OUT/dryrun.log || { say "FAILED: dry-run: $(tail -3 $OUT/dryrun.log | tr '\n' ' ' | cut -c1-300)"; exit 1; }; say "dry-run OK: $(grep -oE 'PLAN \{.*\}' $OUT/dryrun.log | cut -c1-300)"
  sshc "cd $R && uenv run --view=default pytorch/v2.9.1:v2 -- bash -lc 'export SCRATCH=$S HF_HOME=$R/hf_home HF_HUB_CACHE=$R/hf_home/hub HF_HUB_OFFLINE=0 TRANSFORMERS_OFFLINE=0 HF_DATASETS_OFFLINE=1 HF_TOKEN=\$(cat $R/hf_home/token); source $S/venvs/sft5/bin/activate; python cluster/inspect_labels.py --config cluster/configs/R4_full.yaml --train data/arms/R4_full/train.jsonl'" 2>/dev/null | grep -v "rope_parameters" > $OUT/labels_inspection.txt; say "label inspection: $(grep -c "^===" $OUT/labels_inspection.txt) rows inspected"
  bash cluster/preflight.sh 7 "R4_full_train" | tail -1 > $OUT/preflight.txt; cat $OUT/preflight.txt; grep -q '^OK' $OUT/preflight.txt || { say "FAILED: preflight refused"; exit 1; }
  python3 data/make_gate2_brief.py || { say "FAILED: brief"; exit 1; }
  say "astra gate-2 review (seventh)"; python3 data/review_astra.py gate2_full_v7 docs/reviews/briefs/astra_gate2_full_v7.md docs/reviews/ASTRA_gate2_full_v7_20260915.md --model gpt-6-astra --effort xhigh > logs/astra_gate2_full_v7.log 2>&1 || { say "FAILED: review: $(tail -2 logs/astra_gate2_full_v7.log | tr '\n' ' ' | cut -c1-200)"; exit 1; }
  say "verdict: $(grep -m1 -A2 -i '## 1. Verdict' docs/reviews/ASTRA_gate2_full_v7_20260915.md | tail -1 | cut -c1-300)"; say "PRELAUNCH_DONE"
fi
